// TH16 v1.00a Stage 3 BossCard3 — 狛符「独り阿吽の呼吸」 (spell ids 30-33)
// Source: st03bs.ecl.txt BossCard3 855-946; deps BossCard3Dummy 948-994,
// BossCard3_at 1022-1045, BossCard3_at2 1047-1084, BossCard3_at3 1086-1138.
// Source frame s=0 is BossCard3's timerReset (line 866); target card frame = s + ~123
// (120 shell buffer + task startup). TIME_LIMIT covers 120 + 2400 + 4.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// at3 bullet effect chain (source etEx 2 / 256 / WAIT 40 / STEP a=60,b=1,c=1,r=0):
// fly straight, hold cursor 40 frames, decay speed 1.5->0 over 60 frames with the
// birth angle, then at the segment boundary re-aim at the player and set target speed.
// ANIM is omitted by policy except the 4*velocity birth retreat, folded into sh_dist.
xformdef AT3_STEP(target: fx) {
    offscreen_keep(120);   // source etEx type 0x100 a=120, b=0
    @40 add_speed(0fx);    // source etEx WAIT a=40: cursor-only wait, motion continues
    step_speed(0fx, 60);   // source STEP a=60: logical speed decays linearly to 0
    wait(60);
    aim_player(0deg);      // source STEP c=1: re-query player at segment boundary (r=0)
    set_speed(target);     // source STEP s: 0.9 / 0.9 / 2.4 / 2.9 by rank
}

// Shell: control hosts the spell; real boss carries body/hurt boxes and movement.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 30, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Entry position: Boss() leaves the boss at (0,128); BossCard3's first move is
    // movePosTime(60,4,0,144) (line 891), so it is inherited from the previous card.
    _ = spawn_enemy(0fx, 128fx, 1700, 0, 0, 0, boss_card3);
}

// BossCard3_at2 (1047-1084): 1 rice bullet per frame, birth angle 90deg, advance
// +-2deg each shot and an extra +-4deg between 5-shot groups; 120 groups = 600 frames.
async sub at2_stream(step: angle) {
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 4);       // etSprite(1, 8, 4)
    sh_ring(0, 1);                    // etAim(1, 3): fixed full ring, count 1
    sh_aim(0, 0);
    sh_count(0, 1, 1);                // etCount(1, 1, 1) all ranks
    sh_speed(0, 1.1fx, 0fx);          // etSpeed(1, 1.1, 1.0), single layer -> s0
    sh_dist(0, 27.6fx);               // etDist 32 - ANIM 4*1.1
    var a: angle = 90deg;             // %A = 1.570796
    for g in 0..120 {                 // $B = 120
        for i in 0..5 {               // $C = 5
            sh_angle(0, a, 0deg);     // etAngle(1, A, 0)
            a = a + step;             // A += +-%F2
            sh_fire(0);               // etOn(1)
            wait(1);
        }
        a = a + step;                 // A += %F2*2 between groups
        a = a + step;
    }
}

// BossCard3_at3 (1086-1138): big ball every 10/10/7/5 frames (E/N/H/L),
// 60/60/85/120 shots; birth angle 90deg turning by -10*%F2 each shot.
async sub at3_stream(da: angle) {
    var rank: int = global(GVAR_RANK);
    var n: int = 60;                  // diffI($B, 60, 60, 85, 120)
    var gap: int = 10;                // wait([-1]): 10/10/7/5
    var target: fx = 0.9fx;           // STEP s: 0.9/0.9/2.4/2.9
    if rank >= 2 { n = 85; gap = 7; target = 2.4fx; }
    if rank >= 3 { n = 120; gap = 5; target = 2.9fx; }
    sh_reset(0);
    sh_sprite(0, TH16_BIG_BALL, 2);   // etSprite(0, 18, 2)
    sh_ring(0, 1);                    // etAim(0, 3)
    sh_aim(0, 0);
    sh_count(0, 1, 1);                // etCount(0, 1, 1) all ranks
    sh_speed(0, 1.5fx, 0fx);          // etSpeed(0, 1.5, 1.2), single layer -> s0
    sh_dist(0, 10fx);                 // etDist 16 - ANIM 4*1.5
    sh_xform(0, AT3_STEP(target));
    var a: angle = 90deg;             // %A = 1.570796
    for i in 0..n {
        sh_angle(0, a, 0deg);         // etAngle(0, A, 0)
        a = a - da;                   // A -= %F2*10
        sh_fire(0);                   // etOn(0)
        wait(gap);
    }
}

// BossCard3Dummy (948-994). Spawns at the parent final position, moves to (%F0,%F1)
// over 120 frames, then runs both streams and fires a 32/52/64/72-shot ring at +720.
async sub card3_dummy(f0: fx, f1: fx) {
    set_invuln(65535);                // shell: real enemies invulnerable (source setInvuln(120))
    set_hurtbox(16fx);                // setHurtbox(32,32) -> r=16
    set_hitbox(12fx);                 // setHitbox(24,24) -> r=12
    move_to(120, f0, f1, EASE_QUAD_OUT);  // movePosTime(120,4,%F0,%F1)
    wait(120);
    var f2: angle = 2deg;             // %F2 = +-0.034907 rad from own final x
    var f2_10: angle = 20deg;
    if $self_x < 0fx { f2 = -2deg; f2_10 = -20deg; }
    spawn at2_stream(f2);
    spawn at3_stream(f2_10);
    wait(600);
    var n: int = 32;                  // !E 32 !N 52 !H 64 !LO 72
    if global(GVAR_RANK) >= 1 { n = 52; }
    if global(GVAR_RANK) >= 2 { n = 64; }
    if global(GVAR_RANK) >= 3 { n = 72; }
    sh_reset(0);
    sh_sprite(0, TH16_OVAL, 1);       // etSprite(0, 20, 1)
    sh_ring(0, 1);                    // etAim(0, 3)
    sh_aim(0, 0);
    sh_count(0, n, 1);                // etCount(0, [-1], 1)
    sh_speed(0, 2.5fx, 0fx);          // etSpeed(0, 2.5, 1.2), single layer -> s0
    sh_angle(0, 90deg, 0deg);         // etAngle(0, 1.5707964, 0.034906585)
    sh_dist(0, 14fx);                 // etDist 24 - ANIM 4*2.5
    sh_fire(0);                       // etOn(0)
    // source delete(): main task returning despawns the enemy
}

// BossCard3_at (1022-1045), called synchronously from the main script; it blocks
// 120 + 600 frames like the source call. $I0 = RAND%2: 0 -> -1, else +1.
sub boss_at(ax: fx, by: fx) {
    var f0: fx = ax;
    if rand(2) == 0 { f0 = 0fx - ax; }
    var f1: fx = by;
    // enmCreate relative to parent FINAL, i.e. at the boss's current position
    _ = spawn_enemy($self_x, $self_y, 3500, 0, 0, 0, card3_dummy(f0, f1));
    move_to(120, 0fx - f0, f1, EASE_QUAD_OUT);  // movePosTime(120,4,%F0*-1,%F1)
    wait(120);
    var f2: angle = 2deg;
    var f2_10: angle = 20deg;
    if $self_x < 0fx { f2 = -2deg; f2_10 = -20deg; }
    spawn at2_stream(f2);
    spawn at3_stream(f2_10);
    wait(600);
}

// BossCard3 / Boss (855-946, 8-58). Movement baseline:
//  - initial movePosTime(60,4,0,144) from the inherited (0,128)
//  - the source jump to the loop check costs no extra wait; block times are
//    60 / 120 / 180 / 240 and repeat, with each boss_at blocking 720 frames.
//  - moveLimit(0,144,288,128) clamps y to [80,208]; the post-at move to (0,64)
//    is clamped to (0,80), which is what later dummy spawns inherit.
async sub boss_card3() {
    set_invuln(65535);                // shell: real enemy invulnerable
    set_hurtbox(20fx);                // Boss(): setHurtbox(40,40) -> r=20
    set_hitbox(24fx);                 // Boss(): setHitbox(48,48) -> r=24
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);   // 891
    wait(60);
    wait(60);                         // time-120 block
    loop {
        boss_at(96fx, 160fx);         // 911
        move_to(60, 0fx, 80fx, EASE_QUAD_OUT); // 912: (0,64) clamped to y=80
        wait(60);
        wait(60);                     // time-180 block
        boss_at(128fx, 128fx);        // 923
        move_to(60, 0fx, 80fx, EASE_QUAD_OUT); // 924
        wait(60);
        wait(60);                     // time-240 block
        boss_at(64fx, 192fx);         // 935
        move_to(60, 0fx, 80fx, EASE_QUAD_OUT); // 936
        wait(60);
        wait(60);                     // back to the next time-120 block
    }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
